import numpy as np

def shunt_admittance(Y):
    """
    2x2 ABCD for a shunt admittance Y (single polarization).
    [ 1    0 ]
    [  Y   1 ]
    """
    return np.array([[1, 0],
                     [Y, 1]], dtype=complex)

def transmission_line(Z, d, k):
    """
    2x2 ABCD for a uniform transmission line (single polarization):
    [ cos(kd)       jZ sin(kd) ]
    [ j(1/Z) sin(kd) cos(kd)   ]
    """
    beta = k * d
    A = np.cos(beta)
    B = 1j*Z*np.sin(beta)
    C = 1j*(1/Z)*np.sin(beta)
    D = np.cos(beta)

    return np.array([[A, B],
                     [C, D]], dtype=complex)

def metal_sheet_admittance(Y_big=1e9):
    """
    Approximate a perfect electric conductor (PEC) as a huge shunt admittance.
    """
    return np.array([[1, 0],
                     [Y_big, 1]], dtype=complex)

def multiply_abcd(matrices):
    M = np.eye(2, dtype=complex)
    for mat in matrices:
        M = M @ mat
    return M

def extract_s_params(M, Z0):
    """
    Given ABCD = [[A, B], [C, D]], reflection (S11) and transmission (S21):
      S11 = (A + B/Z0 - C*Z0 - D) / (A + B/Z0 + C*Z0 + D)
      S21 =  2                           / (A + B/Z0 + C*Z0 + D)
    """
    A, B, C, D = M[0,0], M[0,1], M[1,0], M[1,1]
    top = (A + B/Z0 - C*Z0 - D)
    bot = (A + B/Z0 + C*Z0 + D)
    S11 = top / bot
    S21 = 2.0 / bot
    return S11, S21

