    wavelength = c0 / freq
    k0 = 2*np.pi / wavelength

    # Free-space impedance and reference
    Z0 = 377.0  # ohms

    # Admittance sweep from 0.005j to 0.014j (in steps)
    Y_vals = (0.1+1j) * np.linspace(0.005, 0.0378, 10) 

    # Air spacer thickness range (meters)
    d_vals = np.linspace(0.0, 0.02, 21)

    best_d = None
    best_phase_range = 0

