    for d in d_vals:
        phase_list = []
        amp_list = []

        for Y in Y_vals:
            # ABCD for "air -> shunt surface -> air spacer -> metal sheet"
            M_surf = shunt_admittance(Y)
            M_spacer = transmission_line(Z0, d, k0)
            M_metal = metal_sheet_admittance(1e9)

            # Multiply
            M_total = multiply_abcd([M_surf, M_spacer, M_metal])

            # Extract reflection S11
            S11, S21 = extract_s_params(M_total, Z0)
            phase_s11 = np.angle(S11)
            phase_list.append(phase_s11)
